"""
Take the regions that move on their own out of a page, so what is left is the part a parameter
could be responsible for.
"""
def remove_dynamic_content(page):
  if not page:
    return page
  for prefix, suffix in settings.DYNAMIC_MARKINGS:
    if prefix is None and suffix is None:
      continue
    elif prefix is None:
      page = re.sub(r"(?s)^.+?" + re.escape(suffix), suffix.replace("\\", r"\\"), page)
    elif suffix is None:
      page = re.sub(r"(?s)" + re.escape(prefix) + r".+$", prefix.replace("\\", r"\\"), page)
    else:
      page = re.sub(r"(?s)" + re.escape(prefix) + r".+?" + re.escape(suffix), prefix.replace("\\", r"\\") + suffix.replace("\\", r"\\"), page)
  return page

"""
The page's own title, or nothing where it has none.

A page can carry a counter, a session id and an advert and still be the same page, while its title is
the one line that names what the target decided to render - so where everything else moves, the title
is what a yes and a no can still be told apart by.
"""
def page_title(page):
  match = re.search(r"(?i)<title\b[^>]*>(?P<result>[^<]*)</title>", page or "")
  return (match.group("result") or "").strip() if match else ""

"""
How alike two pages are, from 0 to 1.

Counted over the characters the two have in common rather than the order they arrive in, because
the ordered reading leaves out every character making up more than one percent of the page: a body
ending in a long run of few distinct characters - base64, hexadecimal, decimals - has every one of
them left out that way, and two such pages a single byte apart read as half alike. A pair too large
to read character by character at all is answered by their lengths, which is the one reading that
costs nothing.
"""
def page_ratio(first, second):
  if first is None or second is None:
    return 0.0
  if first == second:
    return 1.0
  if not first or not second:
    return 0.0
  if max(len(first), len(second)) > settings.MAX_COMPARISON_LENGTH:
    ratio = 1.0 * len(first) / len(second)
    return ratio if ratio <= 1 else 1.0 / ratio
  try:
    return difflib.SequenceMatcher(None, first, second).quick_ratio()
  except (MemoryError, TypeError, ValueError):
    return 0.0

